from pathlib import Path
from xml.sax.saxutils import escape
from lxml import etree
ROOT = Path(__file__).resolve().parents[1]
M = 'gamers_trove_website'
I = '/' + M + '/static/src/img/'

def section(body, cls='', name='Trove content'):
 return f'<section class="gt {cls}" data-snippet="s_text_block" data-name="{name}">{body}</section>'
def intro(kicker,title,text):
 return section(f'<div class="gt-container"><p class="gt-kicker">{kicker}</p><h1>{title}</h1><p>{text}</p></div>', 'gt-page-intro', 'Page introduction')
hero=section(f'''<div class="gt-hero-photo"><img src="{I}hero-players.jpg" alt="Friends enjoying a tabletop game together" fetchpriority="high" width="1800" height="1202"/></div><div class="gt-container gt-hero-content"><div class="gt-hero-copy"><p class="gt-kicker"><span/> THE HOME OF YOUR NEXT ADVENTURE</p><h1>YOUR NEXT<br/>GREAT <em>PLAY.</em></h1><p>Find your game. Build your collection.<br/>Meet your people at Gamer’s Trove.</p><div class="gt-actions"><a href="/shop" class="gt-btn">Shop the Trove <span>↗</span></a><a href="/event" class="gt-btn gt-btn-outline">Enter a tournament <span>↗</span></a></div><div class="gt-hero-caption"><span>01 /</span> SHOP. PLAY. CONNECT.<small>SAN FERNANDO · TRINIDAD &amp; TOBAGO</small></div></div><div class="gt-photo-tag"><span>MAKE TIME TO PLAY</span><strong>GOOD GAMES.<br/>GREAT COMPANY.</strong></div></div>''','gt-hero','Trove hero — edit image, text and links')
strap=section('''<div class="gt-container gt-benefits"><div><span>◈</span><p><strong>A world of games</strong><small>Cards, tabletop &amp; collectibles</small></p></div><div><span>⚑</span><p><strong>Get in the game</strong><small>Tournaments &amp; shared adventures</small></p></div><div><span>⌖</span><p><strong>Your local Trove</strong><small>San Fernando, Trinidad &amp; Tobago</small></p></div></div>''','gt-benefit-strip','Store highlights')
promos=section(f'''<div class="gt-container gt-promos"><a href="/shop" class="gt-promo gt-promo-shop"><div><p class="gt-kicker">THE NEXT CARD. THE NEXT STORY.</p><h2>UPGRADE<br/>YOUR GAME.</h2><span class="gt-text-link">Explore the shop ↗</span></div><span class="gt-promo-dice" aria-hidden="true">✦</span></a><a href="/start-playing" class="gt-promo gt-promo-start"><img src="{I}recap.jpg" alt="Players gathered around a tabletop game" loading="lazy"/><div><p class="gt-kicker">FIRST TIME AT THE TABLE?</p><h2>START YOUR<br/>ADVENTURE.</h2><span class="gt-text-link">Find your first game ↗</span></div></a></div>''','gt-promo-section','Shop and beginner banners')
community=section(f'''<div class="gt-container gt-community-split"><div class="gt-community-photo"><img src="{I}weekends.jpg" alt="Gamer’s Trove players celebrating together" width="600" height="600" loading="lazy"/><span class="gt-photo-caption">GOOD GAMES. GREAT COMPANY.</span></div><div class="gt-community-copy"><p class="gt-kicker">MORE THAN A PLACE TO SHOP</p><h2>FIND YOUR GAME.<br/><em>FIND YOUR PEOPLE.</em></h2><p>The thrill of a close match. The start of a new campaign. The friends you didn’t know you were about to make.</p><p>Gamer’s Trove brings together card players, tabletop adventurers and collectors in San Fernando. Come for your favourite game. Stay for the community.</p><a href="/trove-community" class="gt-btn gt-btn-red">Meet the Trove Titans <span>↗</span></a></div></div>''','gt-section gt-community-section','Trove community')
cta=section('''<div class="gt-container gt-cta"><div><p class="gt-kicker">PULL UP A CHAIR</p><h2>THE NEXT MOVE IS YOURS.</h2></div><a href="/visit-trove" class="gt-btn gt-btn-dark">Visit Gamer’s Trove <span>↗</span></a></div>''','gt-cta-section','Visit call to action')
home=hero+strap+'<t t-call="gamers_trove_website.categories"/><t t-call="gamers_trove_website.products"/>'+promos+'<t t-call="gamers_trove_website.events"/>'+community+cta
about=intro('OUR STORY','FOR THE LOVE<br/>OF THE GAME.','A local store. A shared passion. A whole community of possibilities.')+community+section('''<div class="gt-container gt-editorial-grid"><div><span>01</span><h2>SHOP.</h2><p>Explore trading card games, modern board games, role-playing adventures and fan collectibles. Find something for your next session or your growing collection.</p></div><div><span>02</span><h2>PLAY.</h2><p>Bring your deck and discover organised gaming at the Trove. Check each tournament’s page for the format, entry details, schedule and available tickets.</p></div><div><span>03</span><h2>CONNECT.</h2><p>Get to know players who share your interests. From your first game to your next tournament, there is always another story to share.</p></div></div>''','gt-section','Our purpose')+cta
community_page=intro('THE TROVE TITANS','GOOD GAMES.<br/>GREAT COMPANY.','A look at the people and moments that make Gamer’s Trove.')+section(f'''<div class="gt-container gt-gallery"><figure><img src="{I}weekends.jpg" alt="Community tournament celebration" loading="lazy"/><figcaption>Shared wins. Familiar faces.</figcaption></figure><figure><img src="{I}trade.jpg" alt="A player celebrating at the Trove" loading="lazy"/><figcaption>For the collectors. For the players.</figcaption></figure><figure><img src="{I}recap.jpg" alt="Tabletop players at Gamer’s Trove" loading="lazy"/><figcaption>Another game. Another good memory.</figcaption></figure></div><div class="gt-container gt-social-cta"><h2>KEEP UP WITH THE TROVE.</h2><p>Find community recaps, announcements and more on our official pages.</p><div class="gt-actions"><a t-if="website.gt_instagram" t-att-href="website.gt_instagram" class="gt-btn gt-btn-red" target="_blank" rel="noopener">Instagram ↗</a><a t-if="website.gt_facebook" t-att-href="website.gt_facebook" class="gt-btn gt-btn-dark" target="_blank" rel="noopener">Facebook ↗</a></div></div>''','gt-section','Community gallery')+'<t t-call="gamers_trove_website.events"/>'+cta
visit=intro('VISIT GAMER’S TROVE','YOUR ADVENTURE.<br/>OUR TABLE.','Plan your next visit, ask about a game or get help with an upcoming tournament.')+section(f'''<div class="gt-container gt-visit-grid"><div><img class="gt-visit-photo" src="{I}weekends.jpg" alt="Inside Gamer’s Trove, San Fernando" loading="lazy"/><h2>COME MEET YOUR PEOPLE.</h2><p>Have a question about products, a first visit or tournament entry? Get in touch with the team.</p><a href="/contactus" class="gt-text-link">Send an enquiry →</a></div><t t-call="gamers_trove_website.contact"/></div>''','gt-section','Visit and contact')
beginner=intro('NEW TO THE TABLE?','EVERY GREAT PLAYER<br/>STARTS SOMEWHERE.','A new game. A new adventure. Let’s find your starting point.')+section('''<div class="gt-container gt-editorial-grid"><div><span>01</span><h2>FIND YOUR GAME.</h2><p>Love strategy and collecting? Explore trading card games. Prefer a shared story? Try a role-playing game. Looking for a relaxed evening? Discover board games.</p></div><div><span>02</span><h2>ASK THE TEAM.</h2><p>Tell us what you enjoy, who you’ll be playing with and your budget. Ask about starter options and current availability before choosing your first game.</p></div><div><span>03</span><h2>TAKE A SEAT.</h2><p>Browse upcoming events and check the format, experience level and what to bring. Each event page includes its own registration details.</p></div></div><div class="gt-container gt-faq"><h2>A FEW GOOD QUESTIONS.</h2><details><summary>Do I need experience to visit?</summary><p>You can visit to browse and ask questions. If you want to join a session, contact the team to find an event suited to your experience.</p></details><details><summary>How do I enter a tournament?</summary><p>Open Tournaments, select an event and review its details. Choose an available ticket, enter the attendee information and follow the checkout steps for paid entry.</p></details><details><summary>Where do I find rules and entry requirements?</summary><p>Read the event description before registering. Contact the organiser if you need clarification about deck formats, equipment, age requirements or the event’s cancellation terms.</p></details><details><summary>Can I buy products online?</summary><p>Browse the shop, choose your options and use the cart to checkout. Current prices, availability, payment methods and delivery options are shown in the shop and checkout.</p></details></div>''','gt-section','Getting started')+cta
pages=[('home','Home','/trove-home',home),('about','About Gamer’s Trove','/about-trove',about),('community','The Trove Community','/trove-community',community_page),('visit','Visit Gamer’s Trove','/visit-trove',visit),('beginner','Start Playing','/start-playing',beginner)]
root=etree.Element('odoo');data=etree.SubElement(root,'data',noupdate='1')
for key,title,url,body in pages:
 rec=etree.SubElement(data,'record',id='page_'+key,model='website.page')
 for name,value in [('name',title),('url',url),('type','qweb'),('key',M+'.page_'+key),('website_meta_title',title+' | Gamer’s Trove'),('website_meta_description','Shop tabletop games, join tournaments and meet the Gamer’s Trove community in San Fernando, Trinidad & Tobago.')]:etree.SubElement(rec,'field',name=name).text=value
 etree.SubElement(rec,'field',name='website_id',ref='website.default_website');etree.SubElement(rec,'field',name='is_published',eval='True')
 arch=etree.SubElement(rec,'field',name='arch',type='xml')
 arch.append(etree.fromstring(f'<t t-name="{M}.page_{key}"><t t-call="website.layout"><div id="wrap" class="gt-content oe_structure">{body}</div></t></t>'))
 (ROOT/'preview'/('body-'+key+'.xml')).write_text(body)
(ROOT/M/'data/pages.xml').write_bytes(etree.tostring(root,encoding='utf-8',xml_declaration=True,pretty_print=True))
# Initial category definitions are normal website records, preserved on upgrades.
categories=[('yugioh','Yu-Gi-Oh!','cards'),('magic','Magic: The Gathering','magic'),('rpg','Role-playing games','dice'),('board','Board games','board'),('collectibles','Collectibles','gift'),('accessories','Accessories','shield')]
r=etree.Element('odoo');d=etree.SubElement(r,'data',noupdate='1')
for i,(key,name,icon) in enumerate(categories):
 rec=etree.SubElement(d,'record',id='category_'+key,model='product.public.category')
 for field,v in [('name',name),('sequence',str((i+1)*10)),('gt_icon',icon)]:etree.SubElement(rec,'field',name=field).text=v
 etree.SubElement(rec,'field',name='gt_featured',eval='True');etree.SubElement(rec,'field',name='website_id',ref='website.default_website')
(ROOT/M/'data/categories.xml').write_bytes(etree.tostring(r,encoding='utf-8',xml_declaration=True,pretty_print=True))
print('Built five editable website pages and six native categories.')
